// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.prank(caller);
        string memory v = c.version();

        bytes memory b = bytes(v);
        uint256 dotCount = 0;
        for (uint256 i = 0; i < b.length; i++) {
            if (b[i] == ".") {
                dotCount++;
            }
        }

        assertTrue(dotCount == 2);
    }
}
